            self.total_cost = self.path_cost + self.heuristic_cost
        if other.total_cost is None:
            other.total_cost = other.path_cost + other.heuristic_cost
        return self.total_cost < other.total_cost

    def __repr__(self):
        return f"Node(state={self.state}, path_cost={self.path_cost}, heuristic_cost={self.heuristic_cost}, total_cost={self.total_cost})"

def heuristic(node, goal_node):
    # Define a heuristic function (e.g., Manhattan distance or Euclidean distance)
    # Adjust as per the problem space
    return abs(node.state[0] - goal_node.state[0]) + abs(node.state[1] - goal_node.state[1])

